package com.appliance.itwb.common;

import com.baomidou.mybatisplus.core.incrementer.IdentifierGenerator;
import com.baomidou.mybatisplus.core.toolkit.Sequence;
import org.springframework.stereotype.Component;

/**
 * 统一主键生成器（解决 ORA-01400：无法将 NULL 插入 ID）。
 *
 * <p><b>根因</b>：所有表用了 Oracle {@code GENERATED BY DEFAULT AS IDENTITY}，
 * 而 MyBatis-Plus 的 {@code IdType.INPUT} 在实体主键为 {@code null} 时会把 {@code ID=NULL}
 * 显式写进 INSERT。Oracle 的 IDENTITY 只在"该列被省略"时才自增，显式传 NULL 不会触发，
 * 于是报 ORA-01400。此前库里"不含 ID 列的 INSERT"能成功，正是这个差异的铁证。</p>
 *
 * <p><b>方案</b>：改为由应用层生成主键，彻底绕开 Oracle 序列/IDENTITY 的依赖（库里没有 CREATE SEQUENCE）：</p>
 * <ul>
 *   <li>数值型主键（{@code SysUserSession.id: Long}）→ 实体标 {@code IdType.ASSIGN_ID}，
 *       由本类 {@link #nextId(Object)} 返回雪花 Long；</li>
 *   <li>字符串型主键（各 {@code Wb*.id: String}，底层列仍是 NUMBER）→ 实体标 {@code IdType.ASSIGN_UUID}，
 *       由本类 {@link #nextUUID(Object)} 返回<b>纯数字</b>雪花字符串（可安全落入 NUMBER 列）。</li>
 * </ul>
 *
 * <p><b>关键陷阱（已踩坑）</b>：不能调用 {@code IdWorker.getId(Object) / getIdStr(Object)}——
 * 这两个方法会回委托给全局 {@code IdentifierGenerator}（即本 Bean 自身），导致
 * {@code nextId → IdWorker.getId → nextId → ...} 无限递归 {@code StackOverflowError}。
 * 因此这里直接用 {@code Sequence}（与默认 {@code DefaultIdentifierGenerator} 同一实现），不经过全局生成器。</p>
 *
 * <p><b>向后兼容</b>：MP 仅在主键为 {@code null} 时才调用本生成器（{@code assignId} 用 {@code checkValNull(idValue)} 闸门），
 * 前端/迁移带过来的既有主键不被覆盖，存量数据（小数字符串 id）与新生成的雪花 id 不会冲突。</p>
 *
 * <p><b>装配</b>：{@code MybatisPlusAutoConfiguration} 通过 {@code getBeanThen(IdentifierGenerator.class, ...)}
 * 自动把本 Bean 挂到 {@code GlobalConfig} 上，无需额外配置。</p>
 */
@Component
public class ItwbIdentifierGenerator implements IdentifierGenerator {

    /** 雪花算法序列器（注意：必须用 Sequence 直接生成，禁止走 IdWorker 的全局委托，否则无限递归）。 */
    private final Sequence sequence = new Sequence(null);

    /** 数值型主键（Long 字段）。 */
    @Override
    public Number nextId(Object entity) {
        return sequence.nextId();
    }

    /** 字符串型主键（String 字段，列是 NUMBER）——返回纯数字雪花字符串。 */
    @Override
    public String nextUUID(Object entity) {
        return String.valueOf(sequence.nextId());
    }
}
